        byte[] baseline = File.ReadAllBytes(Path.Combine(textures, "c06-jpeg-rgb444-baseline.jpg"));
        if (baseline[2] != 255 || baseline[3] != 224) throw new InvalidDataException("Expected generated JFIF header");
        int jfifLength = baseline[4] << 8 | baseline[5];
        baseline = baseline.Take(2).Concat(baseline.Skip(4 + jfifLength)).ToArray();
        int frame = 2;
        while (baseline[frame + 1] != 192) frame += 2 + (baseline[frame + 2] << 8 | baseline[frame + 3]);
        foreach (bool late in new[] { false, true })
        {
            int insert = late ? frame + 2 + (baseline[frame + 2] << 8 | baseline[frame + 3]) : 2;
            byte[] adobe = { 255, 238, 0, 14, 65, 100, 111, 98, 101, 1, 100, 0, 0, 0, 0, 0 };
            File.WriteAllBytes(Path.Combine(textures, "c06-jpeg-adobe-high-" + (late ? "late" : "early") + ".jpg"),
                baseline.Take(insert).Concat(adobe).Concat(baseline.Skip(insert)).ToArray());
        }
